const original = $('input js').first().json;
const text = $input.first().json.content[0].text.replace(/```json\n?/g, "").replace(/```/g, "").trim();
const split = JSON.parse(text);

return [{
  json: {
    ...original,
    headline: split.headline,
    subheadline: split.subheadline,
  }
}];
